import type { Metadata } from 'next'
import { headers } from 'next/headers'
import Link from 'next/link'
import { ViewAllPostsButton } from '@/components/ViewAllPostsButton'
import type { Post } from '@/types'

export const metadata: Metadata = {
  title: 'Home - My Blog',
  description: 'Welcome to my blog homepage',
  openGraph: {
    title: 'Home - My Blog',
  },
}

async function getRecentPosts(): Promise<Post[]> {
  const res = await fetch(
    'https://jsonplaceholder.typicode.com/posts?_limit=5',
    { cache: 'no-store' }
  )
  if (!res.ok) {
    throw new Error('Failed to fetch posts')
  }
  return res.json()
}

export interface HomePageProps {
  posts?: Post[]
  userAgent?: string
  timestamp?: string
}

export default async function HomePage(props?: HomePageProps) {
  let userAgent = props?.userAgent
  if (userAgent === undefined) {
    const headersList = await headers()
    userAgent = headersList.get('user-agent') || ''
  }

  const timestamp = props?.timestamp ?? new Date().toISOString()
  const posts = props?.posts ?? (await getRecentPosts())

  return (
    <div>
      <h1>Welcome to My Blog</h1>
      <p>Server-side rendered at: {timestamp}</p>
      <p>Your user agent: {userAgent}</p>

      <h2>Recent Posts</h2>
      <ul>
        {posts.map((post) => (
          <li key={post.id}>
            <Link href={`/blog/${post.id}`}>{post.title}</Link>
          </li>
        ))}
      </ul>

      <ViewAllPostsButton />
    </div>
  )
}

