import { NextRequest, NextResponse } from 'next/server'
import type { PostItem, UpdatePostInput } from '@/types'

export interface RouteContext {
  params: Promise<{ id: string }>
}

export async function GET(
  request: NextRequest,
  context: RouteContext
): Promise<NextResponse<PostItem>> {
  const { id } = await context.params

  // Simulate fetching a single post
  const post: PostItem = {
    id: parseInt(id, 10),
    title: `Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  }

  return NextResponse.json(post, { status: 200 })
}

export async function PUT(
  request: NextRequest,
  context: RouteContext
): Promise<NextResponse<PostItem>> {
  const { id } = await context.params
  let body: Partial<UpdatePostInput> = {}
  try {
    body = await request.json()
  } catch {
    body = {}
  }

  const { title, content } = body

  // Simulate updating a post
  const updatedPost: PostItem = {
    id: parseInt(id, 10),
    title: title || `Post ${id}`,
    content: content || `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  }

  return NextResponse.json(updatedPost, { status: 200 })
}

export async function DELETE(
  request: NextRequest,
  context: RouteContext
): Promise<NextResponse<{ message: string }>> {
  const { id } = await context.params

  // Simulate deleting a post
  return NextResponse.json(
    { message: `Post ${id} deleted successfully` },
    { status: 200 }
  )
}

